import { Component, OnInit } from '@angular/core';
import { FormGroup, FormBuilder, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { IUpdateSellerProfileModel, UpdateSellerProfileModel } from 'src/app/data/model/account/TeacherRegisterModel';
import { UserService } from 'src/app/data/service/user/user.service';
import { IKeyValueViewModel } from '../../../../../data/model/person/BuyerUserModel';

@Component({
  selector: 'app-profile-edit',
  templateUrl: './profile-edit.component.html',
  styleUrls: ['./profile-edit.component.scss']
})
export class ProfileEditComponent implements OnInit {

  form: FormGroup;
  user: IUpdateSellerProfileModel;
  cityId = 1;
  provinceId = 1;

  constructor(
    private userService: UserService,
    private fb: FormBuilder,
    private router: Router,
    public toastController: ToastController,
    public loadingController: LoadingController,
    public alertController: AlertController) { }

  ngOnInit(): void {

    this.form = this.fb.group({
      name: ['', [Validators.required, Validators.maxLength(1000)]],
      family: ['', [Validators.required, Validators.maxLength(1000)]],
      resume: ['فروشنده منتخب اول آموز هستم', [Validators.required, Validators.maxLength(2000)]],
      mainResume: ['فروشنده منتخب اول آموز هستم', [Validators.required, Validators.maxLength(20000)]],
      site: ['', [Validators.maxLength(1000)]],
      telegram: ['', [Validators.maxLength(1000)]],
      instagram: ['', [Validators.maxLength(1000)]],
      linkedIn: ['', [Validators.maxLength(1000)]],
      whatsApp: ['', [Validators.maxLength(1000)]],
      avatar: ['http://localhost:4300/assets/images/avatar.jpg', [Validators.required, Validators.maxLength(200000)]],
      address: ['', [Validators.required, Validators.maxLength(1000)]],
      nationalCode: ['', [Validators.required, Validators.maxLength(13)]],
      identificationCode: ['', [Validators.maxLength(13)]],
      birthDay: ['1370-01-01', [Validators.required]],
      isProductDisabled: [false],
      hasFreeSendPrediction: [false, [Validators.required]],
      freeSendPredictionPrice: [0, [Validators.min(0), Validators.max(10000000000)]],
      minBikeDeliveryPrice: [0, [Validators.required, Validators.min(0), Validators.max(10000000000)]],
      bikeDeliveryPriceEachKg: [0, [Validators.required, Validators.min(0), Validators.max(10000000000)]],
      minTipaxPrice: [0, [Validators.required, Validators.min(0), Validators.max(10000000000)]],
      tipaxPriceEachKg: [0, [Validators.required, Validators.min(0), Validators.max(10000000000)]],
      minPostPrice: [0, [Validators.required, Validators.min(0), Validators.max(10000000000)]],
      postPriceEachKg: [0, [Validators.required, Validators.min(0), Validators.max(10000000000)]],
      minSpecialPostPrice: [0, [Validators.required, Validators.min(0), Validators.max(10000000000)]],
      specialPostPriceEachKg: [0, [Validators.required, Validators.min(0), Validators.max(10000000000)]],
      minBurberryPrice: [0, [Validators.required, Validators.min(0), Validators.max(10000000000)]],
      burberryPriceEachKg: [0, [Validators.required, Validators.min(0), Validators.max(10000000000)]]
    });
  }

  ionViewWillEnter() {

    this.onGetData();
  }

  onBackClick() {

    this.router.navigateByUrl('/SellerPanel');
  }

  async presentAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdate();
          }
        }
      ]
    });

    await alert.present();
  }

  getCityList(): IKeyValueViewModel[] {

    return this.user.cities.filter(e => e.provinceId == this.provinceId);
  }

  onGetData() {

    SharedIonic.loading(this.loadingController);

    this.userService.GetSellerProfileEdit().subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          this.provinceId = res.data.provinceId;
          this.cityId = res.data.cityId;

          this.user = res.data;

          this.form.setValue({
            name: this.user.name,
            family: this.user.family,
            address: this.user.address,
            resume: this.user.resume,
            avatar: this.user.userAvatarAddress,
            nationalCode: this.user.nationalCode,
            identificationCode: this.user.identificationCode,
            birthDay: this.user.birthDay,
            mainResume: this.user.mainResume,
            telegram: this.user.telegram,
            instagram: this.user.instagram,
            whatsApp: this.user.whatsApp,
            linkedIn: this.user.linkedIn,
            site: this.user.site,
            isProductDisabled: res.data.isProductDisabled,
            hasFreeSendPrediction: res.data.hasFreeSendPrediction,
            freeSendPredictionPrice: res.data.freeSendPredictionPrice,
            minBikeDeliveryPrice: res.data.minBikeDeliveryPrice,
            bikeDeliveryPriceEachKg: res.data.bikeDeliveryPriceEachKg,
            minTipaxPrice: res.data.minTipaxPrice,
            tipaxPriceEachKg: res.data.tipaxPriceEachKg,
            minPostPrice: res.data.minPostPrice,
            postPriceEachKg: res.data.postPriceEachKg,
            minSpecialPostPrice: res.data.minSpecialPostPrice,
            specialPostPriceEachKg: res.data.specialPostPriceEachKg,
            minBurberryPrice: res.data.minBurberryPrice,
            burberryPriceEachKg: res.data.burberryPriceEachKg
          });
        } else {
          SharedIonic.toast(this.toastController, 'کاربر یافت نشد');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
      }
    );
  }

  onUpdate() {

    if (!this.form.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    let city = this.user.cities.find(e => e.id == this.cityId);

    if (city == null || city == undefined) {

      this.provinceId = 1;
      this.cityId = 1;
    } else if (this.provinceId != city.provinceId) {

      this.provinceId = 1;
      this.cityId = 1;
    }

    this.userService.UpdateSellerProfileEdit(
      new UpdateSellerProfileModel(
        this.user.id,
        this.form.value.address,
        this.form.value.resume,
        this.form.value.nationalCode,
        this.form.value.identificationCode,
        this.form.value.birthDay,
        this.form.value.avatar,
        this.form.value.name,
        this.form.value.family,
        this.form.value.mainResume,
        this.form.value.site,
        this.form.value.telegram,
        this.form.value.instagram,
        this.form.value.whatsApp,
        this.form.value.linkedIn,
        this.form.value.isProductDisabled,
        this.form.value.hasFreeSendPrediction,
        this.form.value.freeSendPredictionPrice,
        this.form.value.minBikeDeliveryPrice,
        this.form.value.bikeDeliveryPriceEachKg,
        this.form.value.minTipaxPrice,
        this.form.value.tipaxPriceEachKg,
        this.form.value.minPostPrice,
        this.form.value.postPriceEachKg,
        this.form.value.minSpecialPostPrice,
        this.form.value.specialPostPriceEachKg,
        this.form.value.minBurberryPrice,
        this.form.value.burberryPriceEachKg,
        1,
        this.provinceId,
        this.cityId,
        false
      )
    ).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.toast(this.toastController, 'انجام نشد');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
      }
    );
  }
}
